void main() {
  // Item weights and values
  final weights = [2, 3, 4, 5];
  final values = [3, 4, 5, 6];
  final capacity = 5;
  final n = weights.length;

  // Initialize DP table with dimensions (n+1) x (capacity+1)
  final dp = List.generate(n + 1, (i) => List.filled(capacity + 1, 0));

  // Build DP table
  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {
      if (weights[i - 1] <= w) {
        dp[i][w] = (values[i - 1] + dp[i - 1][w - weights[i - 1]]).compareTo(dp[i - 1][w]) > 0
            ? values[i - 1] + dp[i - 1][w - weights[i - 1]]
            : dp[i - 1][w];
      } else {
        dp[i][w] = dp[i - 1][w];
      }
    }
  }

  // Output the maximum value
  print('Maximum value: ${dp[n][capacity]}');
}

