void main() {
  // Adjacency list representation of a DAG (Directed Acyclic Graph)
  final Map<int, List<int>> graph = {
    0: [1, 2],
    1: [3],
    2: [3],
    3: [4],
    4: [],
  };

  // Calculate in-degree for each node
  final Map<int, int> inDegree = {};
  graph.forEach((node, neighbors) {
    inDegree.putIfAbsent(node, () => 0);
    for (final neighbor in neighbors) {
      inDegree.update(neighbor, (value) => value + 1, ifAbsent: () => 1);
    }
  });

  // Initialize queue with nodes having zero in-degree
  final queue = <int>[];
  inDegree.forEach((node, degree) {
    if (degree == 0) queue.add(node);
  });

  // Perform topological sort
  final sorted = <int>[];
  while (queue.isNotEmpty) {
    final node = queue.removeAt(0);
    sorted.add(node);
    for (final neighbor in graph[node]!) {
      inDegree[neighbor] = inDegree[neighbor]! - 1;
      if (inDegree[neighbor] == 0) {
        queue.add(neighbor);
      }
    }
  }

  // Check for cycles (should not occur in a DAG)
  if (sorted.length != graph.length) {
    print('Error: Graph contains a cycle!');
  } else {
    print('Topologically sorted order: $sorted');
  }
}

