void main() {
  // Example graph: List of edges [source, destination, weight]
  final edges = [
    [0, 1, 10],
    [0, 2, 6],
    [0, 3, 5],
    [1, 3, 15],
    [2, 3, 4],
  ];
  final totalVertices = 4;

  // Sort edges by weight
  edges.sort((a, b) => a[2].compareTo(b[2]));

  // Initialize parent array for Union-Find
  final parent = List<int>.generate(totalVertices, (i) => i);

  // Find function with path compression
  int find(int i) {
    if (parent[i] != i) {
      parent[i] = find(parent[i]);
    }
    return parent[i];
  }

  // Union function
  void union(int x, int y) {
    parent[find(x)] = find(y);
  }

  // Kruskal's algorithm
  final mst = <List<int>>[];
  int totalWeight = 0;
  int edgeCount = 0;

  for (final edge in edges) {
    final u = edge[0], v = edge[1], weight = edge[2];
    if (find(u) != find(v)) {
      mst.add(edge);
      totalWeight += weight;
      union(u, v);
      edgeCount++;
      if (edgeCount == totalVertices - 1) break;
    }
  }

  // Output results
  print('Edges in MST:');
  for (final edge in mst) {
    print('${edge[0]} - ${edge[1]} : ${edge[2]}');
  }
  print('Total weight: $totalWeight');
}

