bool wordBreak(String s, List<String> wordDict) {
  final Set<String> words = wordDict.toSet();
  final int n = s.length;
  final List<bool> dp = List<bool>.filled(n + 1, false);
  dp[0] = true;

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && words.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[n];
}

