void main() {
  // Example distance matrix (4 cities)
  List<List<int>> distances = [
    [0, 10, 15, 20],
    [10, 0, 35, 25],
    [15, 35, 0, 30],
    [20, 25, 30, 0]
  ];

  int n = distances.length;
  List<int> cities = List.generate(n, (index) => index);
  List<int> bestPath = [];
  int minDistance = 1 << 30; // Large initial value

  // Generate all permutations starting from city 0
  void permute(List<int> list, int start) {
    if (start == list.length - 1) {
      int currentDistance = 0;
      // Calculate total distance for this permutation
      for (int i = 0; i < list.length - 1; i++) {
        currentDistance += distances[list[i]][list[i + 1]];
      }
      // Add return to start city
      currentDistance += distances[list.last][list.first];

      // Update best path if better
      if (currentDistance < minDistance) {
        minDistance = currentDistance;
        bestPath = List.from(list);
      }
      return;
    }

    for (int i = start; i < list.length; i++) {
      // Swap elements
      List<int> swapped = List.from(list);
      int temp = swapped[start];
      swapped[start] = swapped[i];
      swapped[i] = temp;

      permute(swapped, start + 1);
    }
  }

  permute(cities, 1); // Start permutations from index 1 (keep first city fixed)

  // Add return to start city for output
  bestPath.add(bestPath.first);

  print('Best path: $bestPath');
  print('Minimum distance: $minDistance');
}

