void main() {
  const int n = 8; // Board size (N)
  List<int> board = List.filled(n, -1);
  int solutions = 0;

  bool isSafe(int row, int col) {
    for (int i = 0; i < row; i++) {
      if (board[i] == col ||
          (board[i] - i == col - row) ||
          (board[i] + i == col + row)) {
        return false;
      }
    }
    return true;
  }

  void solveNQueens(int row) {
    if (row == n) {
      solutions++;
      return;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(row, col)) {
        board[row] = col;
        solveNQueens(row + 1);
      }
    }
  }

  solveNQueens(0);
  stdout.write('Number of solutions for $n-Queens: $solutions');
}

