void main() {
  // Example graph represented as an adjacency list
  // Graph with 5 vertices (0 to 4)
  List<List<int>> graph = [
    [1, 3],       // Vertex 0 is connected to 1 and 3
    [0, 2, 4],    // Vertex 1 is connected to 0, 2, and 4
    [1, 3],       // Vertex 2 is connected to 1 and 3
    [0, 2, 4],    // Vertex 3 is connected to 0, 2, and 4
    [1, 3]        // Vertex 4 is connected to 1 and 3
  ];

  int n = graph.length; // Number of vertices
  List<int> path = List.filled(n, -1); // Current path being explored
  bool found = false; // Flag to indicate if a Hamiltonian path is found

  // Helper function to check if vertex can be added at position 'pos' in the path
  bool isSafe(int v, int pos) {
    // Check if vertex is adjacent to the previous vertex in the path
    if (!graph[path[pos - 1]].contains(v)) {
      return false;
    }
    // Check if vertex has not already been included
    for (int i = 0; i < pos; i++) {
      if (path[i] == v) {
        return false;
      }
    }
    return true;
  }

  // Recursive backtracking function to find Hamiltonian path
  bool hamPathUtil(int pos) {
    // If all vertices are included in the path
    if (pos == n) {
      return true;
    }

    // Try different vertices as the next candidate
    for (int v = 0; v < n; v++) {
      if (isSafe(v, pos)) {
        path[pos] = v;
        if (hamPathUtil(pos + 1)) {
          return true;
        }
        path[pos] = -1; // Backtrack
      }
    }
    return false;
  }

  // Initialize path and start from vertex 0
  path[0] = 0;
  found = hamPathUtil(1);

  // Output results
  if (found) {
    print("Hamiltonian path exists:");
    print(path.join(" -> "));
  } else {
    print("No Hamiltonian path exists in the given graph.");
  }
}

