class Node {
  int key;
  Node? left;
  Node? right;
  Node? parent;
  bool isRed;

  Node(this.key, {this.isRed = true});
}

class RedBlackTree {
  Node? root;

  void insert(int key) {
    Node? newNode = Node(key);
    _insertBST(newNode);
    _fixInsert(newNode);
  }

  void _insertBST(Node newNode) {
    Node? parent;
    Node? current = root;

    while (current != null) {
      parent = current;
      if (newNode.key < current.key) {
        current = current.left;
      } else {
        current = current.right;
      }
    }

    newNode.parent = parent;
    if (parent == null) {
      root = newNode;
    } else if (newNode.key < parent.key) {
      parent.left = newNode;
    } else {
      parent.right = newNode;
    }
  }

  void _fixInsert(Node node) {
    while (node.parent != null && node.parent!.isRed) {
      if (node.parent == node.parent!.parent!.left) {
        final uncle = node.parent!.parent!.right;
        if (uncle != null && uncle.isRed) {
          node.parent!.isRed = false;
          uncle.isRed = false;
          node.parent!.parent!.isRed = true;
          node = node.parent!.parent!;
        } else {
          if (node == node.parent!.right) {
            node = node.parent!;
            _leftRotate(node);
          }
          node.parent!.isRed = false;
          node.parent!.parent!.isRed = true;
          _rightRotate(node.parent!.parent!);
        }
      } else {
        final uncle = node.parent!.parent!.left;
        if (uncle != null && uncle.isRed) {
          node.parent!.isRed = false;
          uncle.isRed = false;
          node.parent!.parent!.isRed = true;
          node = node.parent!.parent!;
        } else {
          if (node == node.parent!.left) {
            node = node.parent!;
            _rightRotate(node);
          }
          node.parent!.isRed = false;
          node.parent!.parent!.isRed = true;
          _leftRotate(node.parent!.parent!);
        }
      }
    }
    root!.isRed = false;
  }

  void _leftRotate(Node x) {
    final y = x.right!;
    x.right = y.left;
    if (y.left != null) y.left!.parent = x;
    y.parent = x.parent;
    if (x.parent == null) {
      root = y;
    } else if (x == x.parent!.left) {
      x.parent!.left = y;
    } else {
      x.parent!.right = y;
    }
    y.left = x;
    x.parent = y;
  }

  void _rightRotate(Node x) {
    final y = x.left!;
    x.left = y.right;
    if (y.right != null) y.right!.parent = x;
    y.parent = x.parent;
    if (x.parent == null) {
      root = y;
    } else if (x == x.parent!.right) {
      x.parent!.right = y;
    } else {
      x.parent!.left = y;
    }
    y.right = x;
    x.parent = y;
  }

  void inOrderTraversal([Node? node]) {
    node ??= root;
    if (node == null) return;
    inOrderTraversal(node.left);
    print('${node.key} (${node.isRed ? 'Red' : 'Black'})');
    inOrderTraversal(node.right);
  }
}

