void main() {
  // Implementation of KMP string matching algorithm
  String text = "ABABDABACDABABCABAB";
  String pattern = "ABABCABAB";

  // Precompute the longest prefix suffix (LPS) array
  List<int> computeLPS(String pat) {
    int n = pat.length;
    List<int> lps = List.filled(n, 0);
    int len = 0;
    int i = 1;

    while (i < n) {
      if (pat[i] == pat[len]) {
        len++;
        lps[i] = len;
        i++;
      } else {
        if (len != 0) {
          len = lps[len - 1];
        } else {
          lps[i] = 0;
          i++;
        }
      }
    }
    return lps;
  }

  // Perform KMP search
  void kmpSearch(String txt, String pat) {
    int m = pat.length;
    int n = txt.length;
    List<int> lps = computeLPS(pat);
    int i = 0; // index for txt
    int j = 0; // index for pat

    while (i < n) {
      if (pat[j] == txt[i]) {
        i++;
        j++;
      }
      if (j == m) {
        print("Pattern found at index ${i - j}");
        j = lps[j - 1];
      } else if (i < n && pat[j] != txt[i]) {
        if (j != 0) {
          j = lps[j - 1];
        } else {
          i++;
        }
      }
    }
  }

  // Execute the search
  kmpSearch(text, pattern);
}

@pragma('vm:entry-point')
void main() {
  // Example usage
  String text = "ABAAABCD";
  String pattern = "ABC";

  // Implementation of Boyer-Moore string search
  List<int> boyerMooreSearch(String text, String pattern) {
    if (pattern.isEmpty) return [];

    final n = text.length;
    final m = pattern.length;
    final Map<String, int> badChar = {};
    final List<int> occurrences = [];

    // Preprocess bad character heuristic
    for (int i = 0; i < m; i++) {
      badChar[pattern[i]] = i;
    }

    int shift = 0;
    while (shift <= (n - m)) {
      int j = m - 1;

      // Find mismatch from right
      while (j >= 0 && pattern[j] == text[shift + j]) {
        j--;
      }

      if (j < 0) {
        occurrences.add(shift);
        shift += (shift + m < n) ? m - (badChar[text[shift + m]] ?? -1) : 1;
      } else {
        final bcShift = j - (badChar[text[shift + j]] ?? -1);
        shift += bcShift > 0 ? bcShift : 1;
      }
    }

    return occurrences;
  }

  // Execute search and print results
  final result = boyerMooreSearch(text, pattern);
  print("Pattern found at indices: $result");
}

@pragma('vm:entry-point')
void main() {
  // Sample input string to compress
  String input = "ABABABA";

  // LZW Compression
  Map<String, int> dictionary = {};
  int dictSize = 256;

  // Initialize dictionary with ASCII values
  for (int i = 0; i < 256; i++) {
    dictionary[String.fromCharCode(i)] = i;
  }

  String current = "";
  List<int> compressed = [];

  for (int i = 0; i < input.length; i++) {
    String char = input[i];
    String combined = current + char;

    if (dictionary.containsKey(combined)) {
      current = combined;
    } else {
      compressed.add(dictionary[current]!);
      dictionary[combined] = dictSize++;
      current = char;
    }
  }

  if (current.isNotEmpty) {
    compressed.add(dictionary[current]!);
  }

  print("Original: $input");
  print("Compressed: $compressed");

  // LZW Decompression
  Map<int, String> reverseDict = {};
  for (int i = 0; i < 256; i++) {
    reverseDict[i] = String.fromCharCode(i);
  }

  int rdSize = 256;
  String previous = reverseDict[compressed[0]]!;
  StringBuffer result = StringBuffer(previous);

  for (int i = 1; i < compressed.length; i++) {
    int code = compressed[i];
    String currentStr;

    if (reverseDict.containsKey(code)) {
      currentStr = reverseDict[code]!;
    } else if (code == rdSize) {
      currentStr = previous + previous[0];
    } else {
      throw Exception("Invalid compressed code: $code");
    }

    result.write(currentStr);
    reverseDict[rdSize++] = previous + currentStr[0];
    previous = currentStr;
  }

  print("Decompressed: ${result.toString()}");
}

