void main() {
  // Example: Find the modular inverse of 3 modulo 11
  int a = 3;
  int m = 11;

  int t = 0;
  int newT = 1;
  int r = m;
  int newR = a;

  while (newR != 0) {
    int quotient = r ~/ newR;
    (t, newT) = (newT, t - quotient * newT);
    (r, newR) = (newR, r - quotient * newR);
  }

  if (r > 1) {
    print("$a and $m are not coprime. Modular inverse does not exist.");
    return;
  }

  if (t < 0) {
    t += m;
  }

  print("Modular inverse of $a modulo $m is $t");
}

