  print('After union(1, 4): ${uf.parent}');

  print('find(4) returns: ${uf.find(4)}');
  print('Final parent array: ${uf.parent}');
  print('Are 0 and 4 connected? ${uf.find(0) == uf.find(4)}');
  print('Are 1 and 3 connected? ${uf.find(1) == uf.find(3)}');
