  final graph = [
    [1, 2],    // Node 0
    [0, 3, 4], // Node 1
    [0, 5, 6], // Node 2
    [1],       // Node 3
    [1],       // Node 4
    [2],       // Node 5
    [2]        // Node 6
  ];

  final n = graph.length;
  final parent = List<int>.filled(n, -1);
  final depth = List<int>.filled(n, 0);
  final size = List<int>.filled(n, 0);
  final heavy = List<int>.filled(n, -1);
  final head = List<int>.filled(n, -1);
  final pos = List<int>.filled(n, -1);

  // First DFS to compute subtree sizes and heavy children
  void dfs1(int u, int p) {
    parent[u] = p;
    depth[u] = depth[p] + 1;
    size[u] = 1;
    int maxSize = 0;

    for (final v in graph[u]) {
      if (v == p) continue;
      dfs1(v, u);
      size[u] += size[v];
      if (size[v] > maxSize) {
        maxSize = size[v];
        heavy[u] = v;
      }
    }
  }

  int curPos = 0;

  // Second DFS for chain decomposition
  void dfs2(int u, int h) {
    head[u] = h;
    pos[u] = curPos++;
    if (heavy[u] != -1) dfs2(heavy[u], h);

    for (final v in graph[u]) {
      if (v == parent[u] || v == heavy[u]) continue;
      dfs2(v, v);
    }
  }

  // Execute HLD
  dfs1(0, 0);
  dfs2(0, 0);

  // Print decomposition results
  print('Heavy-Light Decomposition Results:');
  for (int i = 0; i < n; i++) {
    print('Node $i: '
        'Parent=${parent[i]}, '
        'Depth=${depth[i]}, '
        'Size=${size[i]}, '
