void main() {
  // Example graph represented as an adjacency list (index 0 to 7)
  List<List<int>> graph = [
    [1],          // Node 0 -> 1
    [2, 4, 5],    // Node 1 -> 2, 4, 5
    [3, 6],       // Node 2 -> 3, 6
    [2, 7],       // Node 3 -> 2, 7
    [0, 5],       // Node 4 -> 0, 5
    [6],          // Node 5 -> 6
    [5],          // Node 6 -> 5
    [3, 6]        // Node 7 -> 3, 6
  ];

  // Step 1: Create the transpose graph
  List<List<int>> transpose = List.generate(graph.length, (_) => []);
  for (int i = 0; i < graph.length; i++) {
    for (int neighbor in graph[i]) {
      transpose[neighbor].add(i);
    }
  }

  // Step 2: First DFS to fill stack with finishing times
  List<int> stack = [];
  List<bool> visited = List.filled(graph.length, false);
  for (int i = 0; i < graph.length; i++) {
    if (!visited[i]) {
      _dfs(i, graph, visited, stack);
    }
  }

  // Step 3: Second DFS on transpose to get SCCs
  visited = List.filled(graph.length, false);
  List<List<int>> sccs = [];
  while (stack.isNotEmpty) {
    int node = stack.removeLast();
    if (!visited[node]) {
      List<int> component = [];
      _dfsTranspose(node, transpose, visited, component);
      sccs.add(component);
    }
  }

  // Print the SCCs
  print('Strongly Connected Components:');
  for (int i = 0; i < sccs.length; i++) {
    print('Component ${i + 1}: ${sccs[i]}');
  }
}

void _dfs(int node, List<List<int>> graph, List<bool> visited, List<int> stack) {
  visited[node] = true;
  for (int neighbor in graph[node]) {
    if (!visited[neighbor]) {
      _dfs(neighbor, graph, visited, stack);
    }
  }
  stack.add(node);
}

void _dfsTranspose(int node, List<List<int>> transpose, List<bool> visited, List<int> component) {
  visited[node] = true;
  component.add(node);
  for (int neighbor in transpose[node]) {
    if (!visited[neighbor]) {
      _dfsTranspose(neighbor, transpose, visited, component);
    }
  }
}

