class Graph {
  final int vertices;
  final List<List<int>> adj;

  Graph(this.vertices) : adj = List.generate(vertices, (_) => []);

  void addEdge(int u, int v) {
    adj[u].add(v);
    adj[v].add(u);
  }

  List<int> findArticulationPoints() {
    final disc = List<int>.filled(vertices, -1);
    final low = List<int>.filled(vertices, -1);
    final parent = List<int>.filled(vertices, -1);
    final ap = List<bool>.filled(vertices, false);
    var time = 0;

    void dfs(int u) {
      disc[u] = time;
      low[u] = time;
      time++;
      int children = 0;

      for (final v in adj[u]) {
        if (disc[v] == -1) {
          children++;
          parent[v] = u;
          dfs(v);
          low[u] = low[u] < low[v] ? low[u] : low[v];

          if (parent[u] == -1 && children > 1) {
            ap[u] = true;
          }
          if (parent[u] != -1 && low[v] >= disc[u]) {
            ap[u] = true;
          }
        } else if (v != parent[u]) {
          low[u] = low[u] < disc[v] ? low[u] : disc[v];
        }
      }
    }

    for (int i = 0; i < vertices; i++) {
      if (disc[i] == -1) {
        dfs(i);
      }
    }

    return List.generate(vertices, (i) => i).where((i) => ap[i]).toList();
  }
}

