void main() {
  // Example graph represented as an adjacency list
  final graph = {
    0: [1],
    1: [2],
    2: [0, 3],
    3: [4],
    4: [2, 5],
    5: [],
  };

  // Calculate in-degrees and out-degrees
  final inDegree = Map<int, int>.fromIterable(graph.keys, value: (_) => 0);
  final outDegree = Map<int, int>.fromIterable(graph.keys, value: (k) => graph[k]!.length);

  for (final node in graph.keys) {
    for (final neighbor in graph[node]!) {
      inDegree[neighbor] = (inDegree[neighbor] ?? 0) + 1;
    }
  }

  // Check for Eulerian path or circuit conditions
  int startNode = -1;
  int endNode = -1;
  bool hasEulerianPath = true;
  bool hasEulerianCircuit = true;

  for (final node in graph.keys) {
    final out = outDegree[node]!;
    final in_ = inDegree[node]!;

    if (out != in_) {
      hasEulerianCircuit = false;
      if ((out - in_ == 1 && startNode == -1)) {
        startNode = node;
      } else if ((in_ - out == 1 && endNode == -1)) {
        endNode = node;
      } else {
        hasEulerianPath = false;
        break;
      }
    }
  }

  if (!hasEulerianPath && !hasEulerianCircuit) {
    print("Graph has neither Eulerian Path nor Circuit.");
    return;
  }

  // Determine start node for Hierholzer's algorithm
  final start = hasEulerianCircuit ? graph.keys.first : startNode;
  final stack = <int>[start];
  final path = <int>[];
  final localGraph = Map<int, List<int>>.from(graph);

  // Hierholzer's algorithm to find the Eulerian path/circuit
  while (stack.isNotEmpty) {
    final current = stack.last;
    if (localGraph[current]!.isNotEmpty) {
      final next = localGraph[current]!.removeAt(0);
      stack.add(next);
    } else {
      path.add(stack.removeLast());
    }
  }

  // Reverse to get the correct order
  path.reversed.forEach((node) => print("Node: $node"));
  print(hasEulerianCircuit ? "Eulerian Circuit Found." : "Eulerian Path Found.");
}

