    [0, 4, 0, 0, 14, 0],
    [0, 0, 9, 0, 0, 20],
    [0, 0, 0, 7, 0, 4],
    [0, 0, 0, 0, 0, 0]
  ];

  int source = 0;
  int sink = 5;
  int maxFlow = 0;

  // Residual graph initialized with original capacities
  List<List<int>> residualGraph = List.generate(
    graph.length,
    (i) => List<int>.from(graph[i]),
  );

  // Parent array for BFS to store path
  List<int> parent = List.filled(graph.length, -1);

  // Augment flow while there is a path from source to sink
  while (bfs(residualGraph, source, sink, parent)) {
    // Find minimum residual capacity of the path
    int pathFlow = 1 << 60; // Large initial value
    for (int v = sink; v != source; v = parent[v]) {
      int u = parent[v];
      pathFlow = pathFlow < residualGraph[u][v] ? pathFlow : residualGraph[u][v];
    }

    // Update residual capacities and reverse edges
    for (int v = sink; v != source; v = parent[v]) {
      int u = parent[v];
      residualGraph[u][v] -= pathFlow;
      residualGraph[v][u] += pathFlow;
    }

    maxFlow += pathFlow;
  }

  print('Maximum flow: $maxFlow');
}

bool bfs(List<List<int>> graph, int source, int sink, List<int> parent) {
  int n = graph.length;
  List<bool> visited = List.filled(n, false);
  List<int> queue = [];
  queue.add(source);
  visited[source] = true;
  parent[source] = -1;

  while (queue.isNotEmpty) {
    int u = queue.removeAt(0);
    for (int v = 0; v < n; v++) {
      if (!visited[v] && graph[u][v] > 0) {
        if (v == sink) {
          parent[v] = u;
          return true;
        }
        queue.add(v);
        parent[v] = u;
        visited[v] = true;
      }
    }
  }
  return false;
}

