void main() {
  // Example graph representation: adjacency list with capacities and reverse edges
  // Nodes: 0 to n-1, source = 0, sink = 5
  const n = 6;
  List<List<List<int>>> graph = List.generate(n, (_) => []);

  // Add edges: [to, capacity, reverse_edge_index]
  void addEdge(int from, int to, int cap) {
    graph[from].add([to, cap, graph[to].length]);
    graph[to].add([from, 0, graph[from].length - 1]);
  }

  // Build the example flow network (source=0, sink=5)
  addEdge(0, 1, 16);
  addEdge(0, 2, 13);
  addEdge(1, 2, 10);
  addEdge(1, 3, 12);
  addEdge(2, 1, 4);
  addEdge(2, 4, 14);
  addEdge(3, 2, 9);
  addEdge(3, 5, 20);
  addEdge(4, 3, 7);
  addEdge(4, 5, 4);

  int maxFlow = 0;
  const source = 0;
  const sink = 5;

  // Edmonds-Karp algorithm using BFS
  while (true) {
    List<int> parent = List.filled(n, -1);
    List<int> minCap = List.filled(n, 0);
    minCap[source] = 1 << 30; // Large initial capacity
    var queue = [source];
    parent[source] = -2;

    // BFS to find augmenting path
    while (queue.isNotEmpty) {
      int u = queue.removeAt(0);
      for (int i = 0; i < graph[u].length; i++) {
        var edge = graph[u][i];
        int v = edge[0];
        int cap = edge[1];
        if (parent[v] == -1 && cap > 0) {
          parent[v] = u;
          minCap[v] = minCap[u] < cap ? minCap[u] : cap;
          if (v == sink) {
            // Augment path and update residual graph
            maxFlow += minCap[sink];
            int cur = sink;
            while (cur != source) {
              int prev = parent[cur];
              for (var edge in graph[prev]) {
                if (edge[0] == cur) {
                  edge[1] -= minCap[sink];
                  int revIndex = edge[2];
                  graph[cur][revIndex][1] += minCap[sink];
                  break;
                }
              }
              cur = prev;
            }
            queue = [];
            break;
          }
          queue.add(v);
        }
      }
    }
    if (parent[sink] == -1) break; // No more augmenting paths
  }

  print('Maximum flow: $maxFlow');
}

