    'Sam': ['Alice', 'Claire', 'Beth'],
  };

  final womenPrefs = {
    'Alice': ['Mike', 'John', 'Sam'],
    'Beth': ['John', 'Sam', 'Mike'],
    'Claire': ['John', 'Mike', 'Sam'],
  };

  // Initialize all men and women as free
  final engagements = <String, String?>{};
  final nextProposalIndex = <String, int>{};
  for (final man in menPrefs.keys) {
    engagements[man] = null;
    nextProposalIndex[man] = 0;
  }

  // While there exists a free man who hasn't proposed to every woman
  String? freeMan;
  do {
    freeMan = engagements.entries
        .firstWhere(
          (entry) => entry.value == null && nextProposalIndex[entry.key]! < womenPrefs.length,
          orElse: () => const MapEntry('', null),
        )
        .key;
    if (freeMan.isEmpty) break;

    final woman = menPrefs[freeMan]![nextProposalIndex[freeMan]!];
    nextProposalIndex[freeMan] = nextProposalIndex[freeMan]! + 1;

    if (!engagements.containsValue(woman)) {
      // Woman is free, engage with current man
      engagements[freeMan] = woman;
    } else {
      // Woman is engaged, check if she prefers new man
      final currentMan = engagements.entries.firstWhere((entry) => entry.value == woman).key;
      final womanPrefList = womenPrefs[woman]!;
      if (womanPrefList.indexOf(freeMan) < womanPrefList.indexOf(currentMan)) {
        engagements[currentMan] = null;
        engagements[freeMan] = woman;
      }
    }
  } while (freeMan.isNotEmpty);

  // Print results
  print('Stable Matches:');
  engagements.forEach((man, woman) => print('$man is engaged to $woman'));
}

