// Helper class to represent a point
class Point {
  final double x;
  final double y;

  Point(this.x, this.y);
}

// Computes the convex hull using Graham's scan algorithm
List<Point> grahamScan(List<Point> points) {
  if (points.length < 3) return points;

  // Find the point with the lowest y-coordinate (and leftmost if tie)
  Point pivot = points.reduce((curr, next) => 
      (curr.y < next.y) ? curr : 
      (curr.y == next.y && curr.x < next.x) ? curr : next);

  // Sort points by polar angle with pivot
  points.sort((a, b) {
    double orientation = crossProductOrientation(pivot, a, b);
    if (orientation == 0) {
      return distanceSquared(pivot, a).compareTo(distanceSquared(pivot, b));
    }
    return orientation > 0 ? -1 : 1;
  });

  // Build the hull using a stack
  List<Point> hull = [];
  for (Point point in points) {
    while (hull.length >= 2 && 
           crossProductOrientation(hull[hull.length - 2], hull.last, point) <= 0) {
      hull.removeLast();
    }
    hull.add(point);
  }

  return hull;
}

// Computes the cross product orientation for points (p, q, r)
// Returns positive for counter-clockwise, negative for clockwise, zero for collinear
double crossProductOrientation(Point p, Point q, Point r) {
  return (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x);
}

// Computes the squared distance between two points (avoiding sqrt for efficiency)
double distanceSquared(Point a, Point b) {
  double dx = a.x - b.x;
  double dy = a.y - b.y;
  return dx * dx + dy * dy;
}

