// Helper class to represent a point
class Point {
  final double x;
  final double y;
  const Point(this.x, this.y);
}

// Function to compute the cross product of vectors (p1->p2) and (p1->p3)
double _crossProduct(Point p1, Point p2, Point p3) {
  return (p2.x - p1.x) * (p3.y - p1.y) - (p2.y - p1.y) * (p3.x - p1.x);
}

// Function to check if point p lies on segment (a->b)
bool _onSegment(Point a, Point b, Point p) {
  return p.x <= max(a.x, b.x) &&
      p.x >= min(a.x, b.x) &&
      p.y <= max(a.y, b.y) &&
      p.y >= min(a.y, b.y);
}

// Utility functions for min and max of doubles
double max(double a, double b) => a > b ? a : b;
double min(double a, double b) => a < b ? a : b;

// Main intersection check using the orientation method
bool doSegmentsIntersect(Point p1, Point q1, Point p2, Point q2) {
  final double o1 = _crossProduct(p1, q1, p2);
  final double o2 = _crossProduct(p1, q1, q2);
  final double o3 = _crossProduct(p2, q2, p1);
  final double o4 = _crossProduct(p2, q2, q1);

  // General case: segments intersect if orientations are different
  if ((o1 * o2 < 0) && (o3 * o4 < 0)) return true;

  // Check for collinear cases
  if (o1 == 0 && _onSegment(p1, q1, p2)) return true;
  if (o2 == 0 && _onSegment(p1, q1, q2)) return true;
  if (o3 == 0 && _onSegment(p2, q2, p1)) return true;
  if (o4 == 0 && _onSegment(p2, q2, q1)) return true;

  return false;
}

