void main() {
  // Example polygon vertices (counter-clockwise order)
  final List<List<double>> polygon = [
    [0.0, 0.0],
    [4.0, 0.0],
    [5.0, 2.0],
    [3.0, 5.0],
    [1.0, 3.0],
  ];

  // Store triangulation results
  final List<List<List<double>>> triangles = [];

  // Ear clipping triangulation algorithm
  List<List<double>> remainingVertices = List.from(polygon);
  while (remainingVertices.length > 3) {
    bool earFound = false;
    for (int i = 0; i < remainingVertices.length; i++) {
      final List<double> prev = remainingVertices[(i - 1 + remainingVertices.length) % remainingVertices.length];
      final List<double> current = remainingVertices[i];
      final List<double> next = remainingVertices[(i + 1) % remainingVertices.length];

      if (_isEar(prev, current, next, remainingVertices)) {
        triangles.add([prev, current, next]);
        remainingVertices.removeAt(i);
        earFound = true;
        break;
      }
    }
    if (!earFound) {
      print("Error: No ear found - polygon may be self-intersecting or degenerate");
      return;
    }
  }
  triangles.add(remainingVertices); // Add final triangle

  // Print results
  print("Original Polygon: $polygon");
  for (int i = 0; i < triangles.length; i++) {
    print("Triangle ${i + 1}: ${triangles[i]}");
  }
}

bool _isEar(List<double> a, List<double> b, List<double> c, List<List<double>> polygon) {
  if (!_isConvex(a, b, c)) return false;
  for (final vertex in polygon) {
    if (vertex == a || vertex == b || vertex == c) continue;
    if (_pointInTriangle(vertex, a, b, c)) return false;
  }
  return true;
}

bool _isConvex(List<double> a, List<double> b, List<double> c) {
  final cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
  return cross > 0; // Counter-clockwise check
}

bool _pointInTriangle(List<double> p, List<double> a, List<double> b, List<double> c) {
  final double area = 0.5 * (-b[1] * c[0] + a[1] * (-b[0] + c[0]) + a[0] * (b[1] - c[1]) + b[0] * c[1]);
  final double s = 1 / (2 * area) * (a[1] * c[0] - a[0] * c[1] + (c[1] - a[1]) * p[0] + (a[0] - c[0]) * p[1]);
  final double t = 1 / (2 * area) * (a[0] * b[1] - a[1] * b[0] + (a[1] - b[1]) * p[0] + (b[0] - a[0]) * p[1]);
  return s > 0 && t > 0 && (1 - s - t) > 0;
}

