  final input = [1, 2, 3];
  final List<List<int>> permutations = [];

  void backtrack(List<int> current, List<int> remaining) {
    if (remaining.isEmpty) {
      permutations.add(List.from(current));
      return;
    }

    for (int i = 0; i < remaining.length; i++) {
      final newCurrent = List<int>.from(current)..add(remaining[i]);
      final newRemaining = List<int>.from(remaining)..removeAt(i);
      backtrack(newCurrent, newRemaining);
    }
  }

  backtrack([], input);

  for (final perm in permutations) {
    print(perm);
  }
}

