  final indices = List.generate(k, (i) => i);

  // Generate combinations iteratively
  final combinations = <List<int>>[];

  while (true) {
    // Add current combination
    combinations.add(List.generate(k, (i) => elements[indices[i]]));

    // Find rightmost index that can be incremented
    int i = k - 1;
    while (i >= 0 && indices[i] == elements.length - k + i) {
