  // Example graph represented as an adjacency list
  // Page 0 links to pages 1 and 2
  // Page 1 links to page 2
  // Page 2 links to pages 0 and 3
  // Page 3 links to page 0
  final List<List<int>> graph = [
    [1, 2],
    [2],
    [0, 3],
    [0]
  ];

  final int numPages = graph.length;
  final double dampingFactor = 0.85;
  final int maxIterations = 10;
  final double initialRank = 1.0 / numPages;

  // Initialize PageRank values
  List<double> pageRanks = List.filled(numPages, initialRank);

  // Precompute out-degree for each node
  List<int> outDegrees = List.generate(numPages, (i) => graph[i].length);

  // Iterate PageRank algorithm
  for (int iteration = 0; iteration < maxIterations; iteration++) {
    List<double> newPageRanks = List.filled(numPages, 0.0);

    // Calculate contribution from incoming links
    for (int i = 0; i < numPages; i++) {
      for (int incomingPage in graph[i]) {
        newPageRanks[i] += pageRanks[incomingPage] / outDegrees[incomingPage];
      }
      // Apply damping factor
      newPageRanks[i] = (1 - dampingFactor) / numPages + dampingFactor * newPageRanks[i];
    }

    pageRanks = newPageRanks;
  }

  // Print final PageRank values
  print('Final PageRank values after $maxIterations iterations:');
  for (int i = 0; i < numPages; i++) {
    print('Page $i: ${pageRanks[i].toStringAsFixed(6)}');
  }
}

