// Dart program demonstrating native assets integration
// Note: This example simulates native asset usage since Dart doesn't have
// built-in native asset handling in standalone scripts

import 'dart:io';
import 'dart:typed_data';

@pragma('vm:entry-point')
void main() {
  print('Native Assets Integration Demo');
  print('==============================');

  // Simulate loading a native asset (e.g., binary data file)
  final assetPath = 'example_asset.bin';

  try {
    // Read asset file as bytes (simulating native asset loading)
    final file = File(assetPath);
    if (!file.existsSync()) {
      print('Native asset not found at: $assetPath');
      print('Creating simulated asset for demonstration...');
      _createSimulatedAsset(assetPath);
    }

    // Load and process the asset
    final assetBytes = file.readAsBytesSync();
    print('Successfully loaded native asset (${assetBytes.length} bytes)');

    // Process asset data (example: checksum calculation)
    final checksum = _calculateChecksum(assetBytes);
    print('Asset checksum: 0x${checksum.toRadixString(16).padLeft(8, '0')}');

    // Demonstrate parsing structured data from asset
    if (assetBytes.length >= 12) {
      final dataView = ByteData.sublistView(assetBytes);
      final header = dataView.getUint32(0);
      final version = dataView.getUint16(4);
      final payloadSize = dataView.getUint32(6);

      print('Asset header: 0x${header.toRadixString(16)}');
      print('Version: $version');
      print('Payload size: $payloadSize bytes');
    }

  } catch (e) {
    print('Error loading native asset: $e');
  }
}

void _createSimulatedAsset(String path) {
  // Create a sample structured binary asset
  final byteData = ByteData(12 + 20); // Header + sample payload
  byteData.setUint32(0, 0x4E415441); // 'NATA' magic number
  byteData.setUint16(4, 1);          // Version 1
  byteData.setUint32(6, 20);         // Payload size
  byteData.setUint64(10, 0xDEADBEEF, Endian.little); // Sample data

  File(path).writeAsBytesSync(byteData.buffer.asUint8List());
}

int _calculateChecksum(Uint8List data) {
  // Simple checksum calculation
  int checksum = 0;
  for (final byte in data) {
    checksum = (checksum + byte) % 0xFFFFFFFF;
  }
  return checksum;
}

