class Logger {
  final String name;
  final String id;
  int _logCount = 0;

  static final Map<String, Logger> _cache = {};

  // Factory constructor with caching logic
  factory Logger(String name) {
    return _cache.putIfAbsent(name, () => Logger._internal(name));
  }

  // Private constructor
  Logger._internal(this.name) : id = '${name}_${DateTime.now().millisecondsSinceEpoch}';

  void log(String message) {
    _logCount++;
    print('[$name] $_logCount: $message (ID: $id)');
  }
}

