        for (int i = 1; i < p + 1; i++) {
          seq.add(a[i]);
        }
      }
    } else {
      a[t] = a[t - p];
      db(t + 1, p);
      int j = a[t - p] + 1;
      while (j < k) {
        a[t] = j;
        db(t + 1, t);
        j++;
      }
    }
  }

  db(1, 1);

  StringBuffer buf = StringBuffer();
  for (int i in seq) {
    buf.write(String.fromCharCode(i + '0'.codeUnitAt(0)));
  }
  String result = buf.toString() + buf.toString().substring(0, n - 1);
  return result;
}

